class OptimisticConcurrencyError(Exception):
    """Raised when an append operation's expected version does not match the current stream version."""
    pass

class EventStore:
    def __init__(self):
        # In-memory storage of streams; each stream is a list of versioned events.
        self.streams: dict[str, list[dict]] = {}

    def get_events(self, stream_id: str, after_version: int = 0) -> list[dict]:
        """Return all events for *stream_id* with a version greater than *after_version*.

        Parameters
        ----------
        stream_id: str
            Identifier of the event stream.
        after_version: int, optional
            Return events with version > after_version. Must be a non‑negative int.
        """
        if type(stream_id) is not str or not stream_id:
            raise ValueError("stream_id must be a non‑empty string")
        if type(after_version) is not int:
            raise ValueError("after_version must be an int")
        if after_version < 0:
            raise ValueError("after_version cannot be negative")

